    # Defensive defaults
    x, y = 0, 0
    obs = observation or {}
    grid = obs.get("grid", [])
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Helper to check cell safely
    def cell(nx, ny):
        if 0 <= ny < height and 0 <= nx < width:
            return grid[ny][nx]
        return None

    # Try to stay central-ish if possible
    # Prefer staying or moving to any adjacent cell that is empty/neutral
    # Use deterministic scanning: around current position if provided, else center
    current = obs.get("position", None)
    if isinstance(current, (list, tuple)) and len(current) >= 2:
        cx, cy = int(current[0]), int(current[1])
    else:
        cx, cy = width // 2, height // 2

    # Evaluate candidates in a fixed order to be deterministic
    for dx in (0, 1, -1):
        for dy in (0, 1, -1):
            if dx == 0 and dy == 0:
                # Prefer non-move last to allow staying
                pass
            nx, ny = cx + dx, cy + dy
            cellv = cell(nx, ny)
            if cellv in (None, "", "empty"):
                # prefer empty cells
                return [dx, dy]

    # If no empty found, try to move towards a target if detectable
    # Look for any resource or opponent; move away or towards defensively
    # Search for simple signals
    target_dirs = []
    for dirx in (-1, 0, 1):
        for diry in (-1, 0, 1):
            if dirx == 0 and diry == 0:
                continue
            nx, ny = cx + dirx, cy + diry
            c = cell(nx, ny)
            if isinstance(c, str):
                lc = c.lower()
                if "resource" in lc or "food" in lc or "gold" in lc:
                    return [dirx, diry]
                if "enemy" in lc or "opponent" in lc or "pursuer" in lc:
                    # move away if possible
                    target_dirs.append((-dirx, -diry))
    if target_dirs:
        dx, dy = target_dirs[0]
        return [dx, dy]

    # Fallback: stay put
    return [0, 0]

